import sys
def main():
    data=sys.stdin.read().split()
    n=int(data[0])
    py=[0]*(n+2)
    for i in range(n):
        x=int(data[1+2*i]); y=int(data[2+2*i])
        py[x]=y
    comp=[0]*(n+2)
    for x in range(1,n+1):
        m=0
        for q in range(1,n+1):
            if q!=x and ((x<q and py[x]<py[q]) or (x>q and py[x]>py[q])):
                m|=1<<q
        comp[x]=m
    def valid(a,b,c,d):
        M=0
        pts=[]
        for x in range(a+1,b):
            if c<py[x]<d:
                M|=1<<x
                pts.append(x)
        for x in pts:
            if not (comp[x]&M):
                return False
        return True
    MOD=998244353
    dp=[0]*(n+2)
    for j in range(1,n+1):
        v=0
        if valid(0,j,py[j],n+1):
            v=1
        for i in range(1,j):
            if py[i]>py[j] and dp[i] and valid(i,j,py[j],py[i]):
                v+=dp[i]
        dp[j]=v%MOD
    ans=0
    for j in range(1,n+1):
        if valid(j,n+1,0,py[j]):
            ans+=dp[j]
    if valid(0,n+1,0,n+1):
        ans+=1
    print(ans%MOD)
