import sys, bisect, math
def solve(A,B,M):
    N=A*B-1
    target=[A]*(B-1)+[A-1]
    cur=[0]*B
    def lis(a):
        t=[]
        for x in a:
            i=bisect.bisect_left(t,x)
            if i==len(t): t.append(x)
            else: t[i]=x
        return len(t)
    def check(T):
        P=[row[:] for row in T]
        Q={}
        for r,row in enumerate(T):
            for c,v in enumerate(row): Q[v]=(r,c)
        w=[0]*N
        for k in range(N,0,-1):
            r,c=Q[k]
            x=P[r].pop()
            for i in range(r-1,-1,-1):
                row=P[i]
                j=bisect.bisect_left(row,x)-1
                row[j],x=x,row[j]
            w[k-1]=x
        for n in range(N+1):
            low=[v for v in w if v<=n]
            high=[-v for v in w if v>n]
            if lis(low)<=A-1 and lis(high)<=B-1:
                return True
        return False
    cnt=[0]
    T=[[] for _ in range(B)]
    def rec(k):
        if k>N:
            if check(T): cnt[0]+=1
            return
        for r in range(B):
            if cur[r]<target[r] and (r==0 or cur[r-1]>cur[r]):
                T[r].append(k); cur[r]+=1
                rec(k+1)
                T[r].pop(); cur[r]-=1
    rec(1)
    lam=target
    conj=[sum(1 for x in lam if x>j) for j in range(A)]
    prod=1
    for r in range(B):
        for c in range(lam[r]):
            prod*=(lam[r]-c-1)+(conj[c]-r-1)+1
    f=math.factorial(N)//prod
    return f*cnt[0]%M
