from functools import lru_cache
sys.setrecursionlimit(100000)
def brute(M, boxes):
    N=len(boxes)
    @lru_cache(None)
    def f(mask, st):
        best=None
        for t in range(M):
            opts=[0]
            ks=[i for i,(ty,rem) in enumerate(st) if ty==t and rem>0]
            if ks:
                s=list(st); k=ks[0]; s[k]=(t,s[k][1]-1)
                opts.append(1+f(mask, tuple(sorted(s))))
            for j in range(N):
                if not mask>>j&1:
                    V,P=boxes[j]
                    s=list(st)+[(t,V-1)]
                    opts.append(1-P+f(mask|1<<j, tuple(sorted(s))))
            g=max(opts)
            best=g if best is None else min(best,g)
        return best
    return f(0,())
