def solve(data):
    n=data[0]; A=[0]+data[1:n+1]
    L=[0]*(n+2); seen=set()
    for i in range(1,n+1):
        seen.add(A[i]); L[i]=len(seen)
    R=[0]*(n+2); seen=set()
    for j in range(n,0,-1):
        seen.add(A[j]); R[j]=len(seen)
    prev=[0]*(n+2); last_={}
    for j in range(1,n+1):
        prev[j]=last_.get(A[j],0); last_[A[j]]=j
    par=list(range(n+1))
    gap=[0]*(n+1)
    def find(x):
        if x<=0: return 0
        r=x
        while par[r]!=r: r=par[r]
        while par[x]!=r:
            par[x],x=r,par[x]
        return r
    last=0; LV=0; T=0; best=0
    for j in range(2,n):
        idx=j-1; v=L[idx]
        if last==0:
            last=idx; LV=v; T=v
        elif LV>v:
            gap[last]=LV-v; last=idx; LV=v
        else:
            e=last; ev=LV
            while True:
                par[e]=e-1
                f=find(e-1)
                if f==0:
                    last=idx; LV=v; T=v; break
                ng=gap[f]+ev-v
                if ng>0:
                    gap[f]=ng; last=idx; LV=v; break
                ev=gap[f]+ev; e=f
