class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        N = L + 1
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for i in range(N + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        def f(x):
            steps = 0
            while x != 1:
                x = bin(x).count('1')
                steps += 1
            return steps

        cnt = [0] * (L + 2)
        ones = 0
        for i, ch in enumerate(s):
            rem = L - i - 1
            if ch == '1':
                for c in range(0, rem + 1):
                    cnt[ones + c] = (cnt[ones + c] + C[rem][c]) % MOD
                ones += 1

        total = 0
        for c in range(1, L + 1):
            if c == 1:
                good = True
            else:
                good = (1 + f(c) <= k)
            if good:
                total = (total + cnt[c]) % MOD
        return total % MOD

