import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    adj = [0] * n
    idx = 2
    for _ in range(m):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u
    # Gaussian elimination over GF(2), keep fully reduced rows
    R = []  # list of (pivot, row)
    for a in adj:
        for p, r in R:
            if (a >> p) & 1:
                a ^= r
        if a:
            p = (a & -a).bit_length() - 1
            newR = []
            for q, r in R:
                if (r >> p) & 1:
                    r ^= a
                newR.append((q, r))
            R = newR
            R.append((p, a))
    pivots = set(p for p, _ in R)
    free = [c for c in range(n) if c not in pivots]
    B = []
    for f in free:
        vec = 1 << f
        for p, r in R:
            if (r >> f) & 1:
                vec |= 1 << p
        B.append(vec)
    X = []
    for v in range(n):
        val = 0
        for i, b in enumerate(B):
            if (b >> v) & 1:
                val |= 1 << i
        if val == 0:
            print("No")
            return
        X.append(val)
    print("Yes")
    print(" ".join(map(str, X)))

main()

