    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        B = [[[[0]*m for _ in range(n)] for _ in range(4)] for _ in range(2)]
        ans = 0
        for t in (0, 1):
            for k in range(4):
                dr, dc = dirs[k]
                cdr, cdc = dirs[(k+1) % 4]
                rows = range(n-1, -1, -1) if dr == 1 else range(n)
                cols = list(range(m-1, -1, -1)) if dc == 1 else list(range(m))
                Bk = B[t][k]
                B0k2 = B[0][(k+1) % 4]
                for i in rows:
                    Bi = Bk[i]
                    for j in cols:
                        v = grid[i][j]
                        if v == 1:
                            continue
                        need = 0 if v == 2 else 2
                        best = 1
                        ni, nj = i+dr, j+dc
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == need:
                            x = 1 + Bk[ni][nj]
                            if x > best: best = x
                        if t == 1:
                            ci, cj = i+cdr, j+cdc
                            if 0 <= ci < n and 0 <= cj < m and grid[ci][cj] == need:
                                x = 1 + B0k2[ci][cj]
                                if x > best: best = x
                        Bi[j] = best
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    ans = max(ans, 1)
                    for k in range(4):
                        ni, nj = i+dirs[k][0], j+dirs[k][1]
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2:
                            ans = max(ans, 1 + B[1][k][ni][nj])
