from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        rem = list(range(1, n + 1))
        res = []
        prev = None
        for pos in range(n):
            chosen = False
            for idx, x in enumerate(rem):
                p = x % 2
                if prev is not None and p == prev:
                    continue
                left = rem[:idx] + rem[idx + 1:]
                m = len(left)
                if m == 0:
                    cnt = 1
                else:
                    o = sum(1 for v in left if v % 2 == 1)
                    e = m - o
                    np_ = 1 - p
                    if np_ == 1:
                        ok = (o == (m + 1) // 2)
                    else:
                        ok = (e == (m + 1) // 2)
                    cnt = factorial(o) * factorial(e) if ok else 0
                if k <= cnt:
                    res.append(x)
                    rem = left
                    prev = p
                    chosen = True
                    break
                k -= cnt
            if not chosen:
                return []
        return res

