class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        full = (1 << k) - 1
        p = [1 % k] * n
        for j in range(1, n):
            p[j] = p[j - 1] * 10 % k
        w = [0] * h
        for i in range(h):
            j = n - 1 - i
            if j != i:
                w[i] = (p[j] + p[i]) % k
            else:
                w[i] = p[i] % k

        def rot(S, c):
            if c == 0:
                return S
            return ((S << c) | (S >> (k - c))) & full

        reach = [0] * (h + 1)
        reach[h] = 1  # residue 0
        for i in range(h - 1, -1, -1):
            S = reach[i + 1]
            m = 0
            for d in range(10):
                m |= rot(S, d * w[i] % k)
            reach[i] = m

        if not (reach[0] >> 0) & 1 and False:
            return ""
        digits = []
        cur = 0
        for i in range(h):
            found = False
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nc = (cur + d * w[i]) % k
                t = (-nc) % k
                if (reach[i + 1] >> t) & 1:
                    digits.append(d)
                    cur = nc
                    found = True
                    break
            if not found:
                return ""
        half = ''.join(map(str, digits))
        if n % 2 == 0:
            return half + half[::-1]
        return half + half[:-1][::-1]

