class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        a = nums
        n = len(a)
        nxt = [n] * n
        st = []
        for i in range(n - 1, -1, -1):
            while st and a[st[-1]] <= a[i]:
                st.pop()
            nxt[i] = st[-1] if st else n
            st.append(i)
        S = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            S[i] = a[i] * (nxt[i] - i) + S[nxt[i]]
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + a[i]
        sp = [list(range(n))]
        j = 1
        while (1 << j) <= n:
            prev = sp[-1]
            h = 1 << (j - 1)
            cur = []
            for i in range(n - (1 << j) + 1):
                x = prev[i]
                y = prev[i + h]
                if a[y] > a[x]:
                    cur.append(y)
                else:
                    cur.append(x)
            sp.append(cur)
            j += 1

        def qmax(l, r):
            ln = r - l + 1
            t = ln.bit_length() - 1
            x = sp[t][l]
            y = sp[t][r - (1 << t) + 1]
            if a[y] > a[x] or (a[y] == a[x] and y < x):
                return y
            return x

        def cost(l, r):
            p = qmax(l, r)
            return (S[l] - S[p]) + a[p] * (r - p + 1) - (P[r + 1] - P[l])

        ans = 0
        r = 0
        for l in range(n):
            if r < l:
                r = l
            while r + 1 < n and cost(l, r + 1) <= k:
                r += 1
            ans += r - l + 1
        return ans

