        while len(T)>n//2:
            y=heapq.heappop(T); sT-=y; heapq.heappush(B,-y); sB+=y
        while len(T)<n//2:
            y=-heapq.heappop(B); sB-=y; heapq.heappush(T,y); sT+=y
