    data=sys.stdin.buffer.read().split()
    n=int(data[0]); m=int(data[1])
    parent=list(range(n+1)); pot=[0]*(n+1); size=[1]*(n+1)
    def find(x):
        path=[]
        while parent[x]!=x:
            path.append(x); x=parent[x]
        root=x
        acc=0
        for v in reversed(path):
            acc^=pot[v]; pot[v]=acc; parent[v]=root
        return root
    idx=2
    for _ in range(m):
        x=int(data[idx]); y=int(data[idx+1]); z=int(data[idx+2]); idx+=3
        rx=find(x); px=pot[x] if x!=rx else 0
        ry=find(y); py=pot[y] if y!=ry else 0
        if rx==ry:
            if (px^py)!=z:
                print(-1); return
        else:
            if size[rx]<size[ry]:
                rx,ry=ry,rx; px,py=py,px
            parent[ry]=rx; pot[ry]=px^py^z; size[rx]+=size[ry]
    groups={}
    P=[0]*(n+1)
    for v in range(1,n+1):
        r=find(v)
        P[v]=pot[v] if v!=r else 0
        groups.setdefault(r,[]).append(v)
    A=[0]*(n+1)
    for r,mem in groups.items():
        sz=len(mem)
        ones=[0]*30
        for v in mem:
            p=P[v]
            b=0
            while p:
                if p&1: ones[b]+=1
                p>>=1; b+=1
        rv=0
        for b in range(30):
            if 2*ones[b]>sz: rv|=1<<b
        for v in mem:
            A[v]=P[v]^rv
    sys.stdout.write(" ".join(map(str,A[1:]))+"\n")
main()

