def main():
    data = sys.stdin.read().split()
    K = int(data[0]); S = data[1]; T = data[2]
    n, m = len(S), len(T)
    if abs(n - m) > K:
        print("No"); return
    MOD = (1 << 61) - 1
    B = random.randrange(10**6, 10**9)
    def build(s):
        h = [0] * (len(s) + 1)
        x = 0
        for idx, c in enumerate(s):
            x = (x * B + ord(c)) % MOD
            h[idx + 1] = x
        return h
    pw = [1] * (max(n, m) + 1)
    for i in range(1, len(pw)):
        pw[i] = pw[i - 1] * B % MOD
    hs = build(S); ht = build(T)
    def gh(h, a, L):
        return (h[a + L] - h[a] * pw[L]) % MOD
    def ext(i, j):
        lo, hi = 0, min(n - i, m - j)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if gh(hs, i, mid) == gh(ht, j, mid):
                lo = mid
            else:
                hi = mid - 1
        return i + lo
    def valid(i, k):
        return i >= 0 and i <= n and i + k >= 0 and i + k <= m
    i0 = ext(0, 0)
    prev = {0: i0}
    if m - n == 0 and i0 >= n:
        print("Yes"); return
    for d in range(1, K + 1):
        cur = {}
        for k in range(-d, d + 1):
            best = -1
            if k in prev:
                p = prev[k]
                for c in (p, p + 1):
                    if valid(c, k) and c > best:
                        best = c
            if k + 1 in prev:
                c = prev[k + 1] + 1
                if valid(c, k) and c > best:
                    best = c
            if k - 1 in prev:
                c = prev[k - 1]
                if valid(c, k) and c > best:
                    best = c
            if best < 0:
                continue
            cur[k] = ext(best, best + k)
        prev = cur
        if (m - n) in prev and prev[m - n] >= n:
            print("Yes"); return
    print("No")
main()

