import sys, random
def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); q = int(data[1])
    A = data[2:2+n]; B = data[2+n:2+2*n]
    w = {}
    rnd = random.getrandbits
    def weight(x):
        v = w.get(x)
        if v is None:
            v = rnd(64) | 1
            w[x] = v
        return v
    pa = [0]*(n+1); pb = [0]*(n+1)
    s = 0
    for i in range(n):
        s += weight(A[i]); pa[i+1] = s
    s = 0
    for i in range(n):
        s += weight(B[i]); pb[i+1] = s
    out = []
    idx = 2+2*n
    for _ in range(q):
        l = int(data[idx]); r = int(data[idx+1]); L = int(data[idx+2]); R = int(data[idx+3])
        idx += 4
        if r-l != R-L:
            out.append("No")
        elif pa[r]-pa[l-1] == pb[R]-pb[L-1]:
            out.append("Yes")
        else:
            out.append("No")
    sys.stdout.write("\n".join(out)+"\n")
main()

