        n = len(nums)
        P = [0] * (n + 1)
        for i, x in enumerate(nums):
            P[i + 1] = P[i] + x
        INF = float('inf')
        mn = [INF] * k
        best = -INF
        for j in range(k, n + 1):
            i = j - k
            r = i % k
            if P[i] < mn[r]:
                mn[r] = P[i]
            v = P[j] - mn[r]
            if v > best:
                best = v
        return int(best)

