import sys, bisect, math

def main():
    N = int(sys.stdin.read().split()[0])
    S = math.isqrt(N)
    sieve = bytearray([1]) * (S + 2)
    sieve[0] = 0
    if S + 2 > 1:
        sieve[1] = 0
    for i in range(2, math.isqrt(S + 1) + 1):
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(range(i*i, S + 2, i)))
    primes = [i for i in range(S + 1) if sieve[i]]
    count = 0
    # p^8 <= N
    for p in primes:
        if p ** 8 <= N:
            count += 1
        else:
            break
    # p^2 q^2 <= N with p < q  <=>  p*q <= S
    for p in primes:
        if p * (p + 1) > S:
            break
        hi = bisect.bisect_right(primes, S // p)
        lo = bisect.bisect_right(primes, p)
        if hi > lo:
            count += hi - lo
    print(count)

main()

