class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        for _ in range(t):
            z = cnt[25]
            new = [0] * 26
            for c in range(25):
                new[c + 1] = cnt[c]
            new[0] = (new[0] + z) % MOD
            new[1] = (new[1] + z) % MOD
            cnt = [x % MOD for x in new]
        return sum(cnt) % MOD

