import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIM = 10000
        sieve = [True] * LIM
        sieve[0] = sieve[1] = False
        for i in range(2, int(LIM ** 0.5) + 1):
            if sieve[i]:
                for j in range(i * i, LIM, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        k = len(str(n))
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d != dist.get(u, INF):
                continue
            if u == m:
                return d
            for i in range(k):
                p = 10 ** (k - 1 - i)
                digit = (u // p) % 10
                cands = []
                if digit < 9:
                    cands.append(u + p)
                if digit > 0:
                    cands.append(u - p)
                for v in cands:
                    if v < 0 or v >= LIM or sieve[v]:
                        continue
                    nd = d + v
                    if nd < dist.get(v, INF):
                        dist[v] = nd
                        heapq.heappush(pq, (nd, v))
        return -1

