import numpy as np
class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0]*n
        z[0] = n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l, r = i, i + z[i]
        d = np.array([j - z[j] for j in range(n)], dtype=np.int64)
        total = 0
        for i in range(1, n - 1):
            countB = int(np.count_nonzero(d[i+1:n] <= i))
            total += countB
            if z[i] >= i:
                total += max(0, n - 2*i)
                if 2*i <= n-1:
                    total -= int(np.count_nonzero(d[2*i:n] <= i))
        return total

