class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = {}
        for a, b in states:
            dp[(a, b)] = cost[0][a] + cost[n - 1][b]
        for i in range(1, n // 2):
            ci = cost[i]
            cj = cost[n - 1 - i]
            ndp = {}
            for a, b in states:
                best = INF
                for pa, pb in states:
                    if pa != a and pb != b:
                        v = dp[(pa, pb)]
                        if v < best:
                            best = v
                ndp[(a, b)] = best + ci[a] + cj[b]
            dp = ndp
        return int(min(dp.values()))

