import random
def brute(W, blocks, maxT):
    # blocks: list of (x,y); returns removal step list
    cur = set(blocks)
    removals = []
    for t in range(1, maxT+1):
        row1 = [b for b in cur if b[1]==1]
        if len(row1)==W:
            removals.append(t)
            cur = set(b for b in cur if b[1]!=1)
        nxt = set()
        for (x,y) in sorted(cur, key=lambda b:b[1]):
            if y==1 or (x,y-1) in nxt:
                nxt.add((x,y))
            else:
                nxt.add((x,y-1))
        cur = nxt
    return removals

def formula(W, blocks, K):
    cols = {}
    for x,y in blocks: cols.setdefault(x,[]).append(y)
    for x in cols: cols[x].sort()
    res=[]
    for k in range(1,K+1):
        if any(len(cols.get(x,[]))<k for x in range(1,W+1)):
            break
        m=0
        for x in range(1,W+1):
            ys=cols[x]
            m=max(m,max(ys[j-1]-j for j in range(1,k+1)))
        res.append(m+k)
    return res

