class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = set(map(tuple, points))
        best = -1
        for (x1, y1) in pts:
            for (x2, y2) in pts:
                if x2 <= x1 or y2 <= y1:
                    continue
                if (x1, y2) not in pts or (x2, y1) not in pts:
                    continue
                ok = True
                for (px, py) in pts:
                    if x1 <= px <= x2 and y1 <= py <= y2:
                        if (px, py) in ((x1, y1), (x1, y2), (x2, y1), (x2, y2)):
                            continue
                        ok = False
                        break
                if ok:
                    area = (x2 - x1) * (y2 - y1)
                    if area > best:
                        best = area
