from typing import List
class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        L = -10**19
        R = 10**19
        base = original[0]
        for i in range(len(original)):
            d = original[i] - base
            u, v = bounds[i]
            if u - d > L:
                L = u - d
            if v - d < R:
                R = v - d
        return max(0, R - L + 1)

